    // deletes and integrity failures are exercised on both runtimes.
    $create=$db->query("SHOW CREATE TABLE `$sourceDatabase`.`$table`")->fetch(PDO::FETCH_NUM)[1];
    $db->exec($create);
    $db->exec("INSERT INTO `$table` SELECT * FROM `$sourceDatabase`.`$table`");
}
